@dataclass(frozen=True)
class Task:
    id:str
    app:str
    kind:str
    split:str
    prompt:str
    def to_dict(self):return asdict(self)

def tasks(split='all'):
    result=[]
    for app,contract in CONTRACTS.items():
        for kind in ('create','edit','feature','bug'):
            change=contract if kind=='create' else (f"Change only the main heading to '{TITLES[app]}' and the '{PRIMARY[app]}' button background to #7c3aed. Preserve all behaviour." if kind=='edit' else FEATURES[app] if kind=='feature' else BUGS[app])
            result.append(Task(app+'.'+kind,app,kind,'holdout',COMMON+'\n'+change+('\n\nExisting app contract:\n'+contract if kind!='create' else '')))
    return result if split in ('all','holdout') else []
def get_task(id):return next(t for t in tasks() if t.id==id)
